+  uint64_t x = ((uint64_t)xsubi[2] << 32) | ((uint64_t)xsubi[1] << 16) | xsubi[0];
+  x = (0x5DEECE66DULL * x + 0xBULL) & 0xFFFFFFFFFFFFULL;
+  xsubi[0] = (unsigned short)(x & 0xFFFF);
+  xsubi[1] = (unsigned short)((x >> 16) & 0xFFFF);
+  xsubi[2] = (unsigned short)((x >> 32) & 0xFFFF);
+  return (double)x * (1.0 / 281474976710656.0);
