+      out_rgba[idx + 2] = (uint8_t)toInt(c.z);
+      out_rgba[idx + 3] = 255;
+    }
+  }
+}
+
+void render_frame(uint8_t *out_rgba, int w, int h, int samps) {
+  render_rows(out_rgba, w, h, samps, 0, h);
+}
