+
+      async function loadEnvelopeIntoVerifier(envelope) {
+        currentSignedEnvelope = JSON.parse(JSON.stringify(envelope));
+        lastAuthenticEnvelopeBackup = JSON.parse(JSON.stringify(envelope));
+        verifierJsonInput.value = JSON.stringify(envelope, null, 2);
+        await runVerificationFromInspector();
+      }
+
+      async function runVerificationFromInspector() {
+        let parsed;
+        try {
+          parsed = JSON.parse(verifierJsonInput.value);
+        } catch (err) {
+          verifyBanner.className = 'verify-banner invalid';
+          verifyStatusTitle.textContent = 'MALFORMED JSON SYNTAX';
+          verifyStatusBadge.className = 'algo-badge classical';
+          verifyStatusBadge.textContent = 'PARSE ERROR';
+          verifyStatusSummary.textContent = 'The verifier input is not valid JSON: ' + err.message;
+          verifyChecksList.innerHTML = '<li>✗ Fix JSON syntax errors before verifying cryptographic signature.</li>';
+          return;
+        }
+
+        let pubKeyOverride = null;
+        const mode = verifyKeySource.value;
+        if (mode === 'active' && activeKeyObj) {
+          pubKeyOverride = activeKeyObj.publicKeyPem;
+        } else if (mode === 'custom') {
+          pubKeyOverride = customPubkeyInput.value.trim();
+        }
+
+        const result = await verifySignedEnvelope(parsed, pubKeyOverride);
+
+        verifyBanner.className = 'verify-banner ' + (result.valid ? 'valid' : 'invalid');
+        verifyStatusTitle.textContent = result.title;
+        verifyStatusBadge.className = 'algo-badge ' + (result.quantumResistant ? 'quantum' : 'classical');
+        verifyStatusBadge.textContent = result.valid ? `VERIFIED (${result.algorithm || 'OK'})` : 'INVALID / TAMPERED';
+        verifyStatusSummary.textContent = result.summary;
+
+        verifyChecksList.innerHTML = result.checks
+          .map((c) => `<li><span>${c.ok ? '✔' : '✘'}</span> <span>${c.text}</span></li>`)
+          .join('');
+      }
+
+      async function signAndPublishPayload(payload) {
+        if (!activeKeyObj) {
+          activeKeyObj = await generateKeyPairForScheme(algoSelect.value);
+          updateKeyringUI();
+        }
+        const envelope = await signDocumentPayload(payload, activeKeyObj);
+        signedLedger.unshift(envelope);
+        renderSignedTicketPreview(envelope);
+        renderLedger();
+        await loadEnvelopeIntoVerifier(envelope);
+        return envelope;
+      }
+
+      // =========================================================================
+      // 5. EVENT LISTENERS & INITIALIZATION
+      // =========================================================================
+      algoSelect.addEventListener('change', async () => {
+        activeKeyObj = await generateKeyPairForScheme(algoSelect.value);
+        updateKeyringUI();
