+      const submitBtn = document.getElementById('create-account-btn');
+      const confirmationBox = document.getElementById('registration-confirmation');
+      const confirmationHeading = document.getElementById('confirmation-heading');
+      const confirmationMessage = document.getElementById('confirmation-message');
+
+      form.addEventListener('submit', (e) => {
+        e.preventDefault();
+
+        // Check honeypot field for automated spam bots
+        const honeypot = document.getElementById('company-website');
+        if (honeypot && honeypot.value.trim() !== '') {
+          return;
+        }
+
+        // Validate all steps in order
+        for (let step = 1; step <= 3; step += 1) {
+          if (!validateStep(step)) {
+            if (currentStep !== step) {
+              updateStepUI(step);
+              validateStep(step);
+            }
+            return;
+          }
+        }
+
+        // Disable submit button AFTER valid submission to prevent double-posts
+        if (submitBtn) {
+          submitBtn.disabled = true;
+          submitBtn.setAttribute('aria-busy', 'true');
+          submitBtn.textContent = 'Creating Account...';
+        }
+
+        const formData = new FormData(form);
+        const rawName = String(formData.get('full_name') || 'Coffee Lover').trim();
+        const rawEmail = String(formData.get('email') || '').trim();
+
+        // Update step indicators to completed
+        stepIndicators.forEach((indicator) => {
+          indicator.classList.remove('step-active');
+          indicator.classList.add('step-done');
+          indicator.removeAttribute('aria-current');
+        });
+
+        form.hidden = true;
+        if (errorSummary) {
+          errorSummary.hidden = true;
+        }
+
+        if (confirmationBox && confirmationMessage) {
+          // Use textContent (never innerHTML) to prevent DOM XSS
+          confirmationMessage.textContent = `Thank you, ${rawName}! Your Daily Grind Rewards account has been created and a confirmation email has been sent to ${rawEmail}.`;
+          confirmationBox.hidden = false;
+          if (confirmationHeading) {
+            confirmationHeading.focus();
+          }
+        }
+      });
