+  <script>
+    (function () {
+      const board = document.querySelector('.kanban-board');
+      if (!board) return;
+
+      let draggedCard = null;
+
+      function updateColumnCounts() {
+        const columns = board.querySelectorAll('.board-column');
+        columns.forEach((col) => {
+          const countEl = col.querySelector('.column-count');
+          if (countEl) {
+            countEl.textContent = String(col.querySelectorAll('.card').length);
+          }
+        });
+      }
+
+      function moveItemToColumn(item, column, referenceNode = null) {
+        if (!item || !column) return;
+        if ('moveBefore' in Element.prototype) {
+          column.moveBefore(item, referenceNode);
+        } else {
+          column.insertBefore(item, referenceNode);
+        }
+        updateColumnCounts();
+      }
+
+      function getDragAfterElement(column, y) {
+        const cards = [...column.querySelectorAll('.card:not(.dragging)')];
+        let closest = { offset: Number.NEGATIVE_INFINITY, element: null };
+
+        for (const child of cards) {
+          const box = child.getBoundingClientRect();
+          const offset = y - box.top - box.height / 2;
+          if (offset < 0 && offset > closest.offset) {
+            closest = { offset, element: child };
+          }
+        }
+        return closest.element;
+      }
+
+      board.addEventListener('dragstart', (event) => {
+        const card = event.target.closest('.board-column .card');
+        if (!card) return;
+        draggedCard = card;
+        card.classList.add('dragging');
+        if (event.dataTransfer) {
+          event.dataTransfer.effectAllowed = 'move';
+          event.dataTransfer.setData('text/plain', card.id);
+        }
+      });
+
+      board.addEventListener('dragend', () => {
+        if (draggedCard) {
+          draggedCard.classList.remove('dragging');
+          draggedCard = null;
+        }
+        board.querySelectorAll('.board-column.drag-over').forEach((col) => {
+          col.classList.remove('drag-over');
+        });
+      });
+
+      board.addEventListener('dragover', (event) => {
+        const column = event.target.closest('.board-column');
+        if (!column) return;
+        event.preventDefault();
+        if (event.dataTransfer) {
+          event.dataTransfer.dropEffect = 'move';
+        }
+        column.classList.add('drag-over');
+      });
+
+      board.addEventListener('dragleave', (event) => {
+        const column = event.target.closest('.board-column');
+        if (column && !column.contains(event.relatedTarget)) {
+          column.classList.remove('drag-over');
+        }
+      });
