+        const img = new Image();
+        img.crossOrigin = 'anonymous';
+        img.onload = function () {
+          gl.bindTexture(gl.TEXTURE_2D, texture);
+          gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, img);
+          gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
+          gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
+          gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
+        };
+        img.src = 'https://images.unsplash.com/photo-1559056199-641a0ac8b55e?auto=format&fit=crop&w=512&q=80';
+
+        gl.enable(gl.DEPTH_TEST);
+        gl.enable(gl.CULL_FACE);
+      }
+
+      function makePerspective(fov, aspect, near, far) {
+        const f = 1.0 / Math.tan(fov / 2);
+        const nf = 1 / (near - far);
+        return new Float32Array([
+          f / aspect, 0, 0, 0,
+          0, f, 0, 0,
+          0, 0, (far + near) * nf, -1,
+          0, 0, (2 * far * near) * nf, 0
+        ]);
+      }
+
+      function computeModelMatrices(rx, ry, tz) {
+        const cx = Math.cos(rx), sx = Math.sin(rx);
+        const cy = Math.cos(ry), sy = Math.sin(ry);
+
+        // R = Rx(rx) * Ry(ry)
+        // Column-major 4x4 matrix
+        const mv = new Float32Array([
+          cy,       sx * sy,      -cx * sy, 0,
+          0,        cx,            sx,      0,
+          sy,      -sx * cy,       cx * cy, 0,
+          0,        0,             tz,      1
+        ]);
+
+        const normalMat = new Float32Array([
+          cy,  sx * sy, -cx * sy,
+          0,   cx,       sx,
+          sy, -sx * cy,  cx * cy
+        ]);
+
+        return { mv, normalMat };
+      }
+
+      function resize() {
+        const rect = canvas.parentElement.getBoundingClientRect();
+        const w = Math.max(1, Math.floor(rect.width));
+        const h = Math.max(1, Math.floor(rect.height));
+        if (canvas.width !== w || canvas.height !== h) {
+          canvas.width = w;
+          canvas.height = h;
+        }
+        // Match CSS 3D perspective exact focal length (f_px) to WebGL vertical FOV
+        const perspectivePx = (0.5 * h) / Math.tan(fovRad / 2);
+        viewport.style.perspective = `${perspectivePx.toFixed(2)}px`;
+      }
+
+      window.addEventListener('resize', resize);
+      resize();
+
+      function render() {
+        resize();
+
+        if (isSpinning) {
+          rotY += spinSpeed;
+        }
+
+        // Render WebGL 3D coffee box
+        if (gl && program) {
+          gl.viewport(0, 0, canvas.width, canvas.height);
+          gl.clearColor(0, 0, 0, 0);
+          gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
+
+          const aspect = canvas.width / canvas.height;
+          const proj = makePerspective(fovRad, aspect, 10, 3000);
+          const { mv, normalMat } = computeModelMatrices(rotX, rotY, -cameraZ);
+
+          gl.useProgram(program);
+
+          const uProj = gl.getUniformLocation(program, 'uProjection');
+          const uMV = gl.getUniformLocation(program, 'uModelView');
+          const uNorm = gl.getUniformLocation(program, 'uNormalMatrix');
+          gl.uniformMatrix4fv(uProj, false, proj);
+          gl.uniformMatrix4fv(uMV, false, mv);
+          gl.uniformMatrix3fv(uNorm, false, normalMat);
+
+          const aPos = gl.getAttribLocation(program, 'aPosition');
+          gl.bindBuffer(gl.ARRAY_BUFFER, posBuffer);
+          gl.enableVertexAttribArray(aPos);
+          gl.vertexAttribPointer(aPos, 3, gl.FLOAT, false, 0, 0);
+
+          const aNorm = gl.getAttribLocation(program, 'aNormal');
+          gl.bindBuffer(gl.ARRAY_BUFFER, normBuffer);
+          gl.enableVertexAttribArray(aNorm);
+          gl.vertexAttribPointer(aNorm, 3, gl.FLOAT, false, 0, 0);
+
+          const aUV = gl.getAttribLocation(program, 'aUV');
+          gl.bindBuffer(gl.ARRAY_BUFFER, uvBuffer);
+          gl.enableVertexAttribArray(aUV);
+          gl.vertexAttribPointer(aUV, 2, gl.FLOAT, false, 0, 0);
+
+          const aFaceId = gl.getAttribLocation(program, 'aFaceId');
+          gl.bindBuffer(gl.ARRAY_BUFFER, faceIdBuffer);
+          gl.enableVertexAttribArray(aFaceId);
+          gl.vertexAttribPointer(aFaceId, 1, gl.FLOAT, false, 0, 0);
+
+          gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, indexBuffer);
+          gl.drawElements(gl.TRIANGLES, numIndices, gl.UNSIGNED_SHORT, 0);
+        }
