+        // Project the interactive HTML form onto the spinning front face of the 3D coffee box
+        // In CSS 3D space (Y-down), WebGL's rotation (rx, ry) corresponds to (-rx, ry)
+        // We also offset Z by (perspective - cameraZ) so depth scaling matches the WebGL camera at Z = cameraZ
+        const perspectivePx = parseFloat(viewport.style.perspective) || 900;
+        const cssZOffset = perspectivePx - cameraZ;
+        const degX = (-rotX * 180) / Math.PI;
+        const degY = (rotY * 180) / Math.PI;
+
+        formPanel.style.transform =
+          `translateZ(${cssZOffset.toFixed(2)}px) ` +
+          `rotateX(${degX.toFixed(3)}deg) ` +
+          `rotateY(${degY.toFixed(3)}deg) ` +
+          `translateZ(${(hz + 1.5).toFixed(2)}px)`;
+
+        requestAnimationFrame(render);
+      }
+
+      requestAnimationFrame(render);
+    })();
+  </script>
 </body>

