--- /dev/null
+++ b/src/utils/webauthnClient.ts
@@ -0,0 +1,370 @@
+export interface ClientPasskey {
+  id: string;
+  publicKey: string;
+  name: string;
+  createdAt: string;
+  lastUsedAt: string | null;
+  transports: AuthenticatorTransport[];
+  deviceType: 'singleDevice' | 'multiDevice';
+  backedUp: boolean;
+  aaguid: string;
+  signCount: number;
+}
+
+export interface ClientUserProfile {
+  id: string;
+  username: string;
+  displayName: string;
+  email: string;
+  subscriptionTier: 'Free Reader' | 'Digital All-Access' | 'Print + Digital';
+  hasPassword: boolean;
+  createdAt: string;
+  lastReauthenticatedAt?: string | null;
+  passkeys: ClientPasskey[];
+}
+
+const STORAGE_USER_KEY = 'dtt_active_user';
+const STORAGE_REAUTH_KEY = 'dtt_last_reauth_ts';
+
+export function base64UrlToUint8Array(base64Url: string): Uint8Array {
+  const padding = '='.repeat((4 - (base64Url.length % 4)) % 4);
+  const base64 = (base64Url + padding).replace(/-/g, '+').replace(/_/g, '/');
+  const rawData = window.atob(base64);
+  const outputArray = new Uint8Array(rawData.length);
+  for (let i = 0; i < rawData.length; ++i) {
+    outputArray[i] = rawData.charCodeAt(i);
+  }
+  return outputArray;
+}
+
+export function bufferToBase64Url(buffer: ArrayBuffer): string {
+  const bytes = new Uint8Array(buffer);
+  let binary = '';
+  for (let i = 0; i < bytes.byteLength; i++) {
+    binary += String.fromCharCode(bytes[i]);
+  }
+  return window
+    .btoa(binary)
+    .replace(/\+/g, '-')
+    .replace(/\//g, '_')
+    .replace(/=+$/, '');
+}
+
+export function getApiUrl(): string {
+  const base = import.meta.env.BASE_URL || '/';
+  const normalizedBase = base.endsWith('/') ? base : `${base}/`;
+  return `${normalizedBase}api/passkeys`;
+}
+
+export function getAppPath(subpath: string): string {
+  const base = import.meta.env.BASE_URL || '/';
+  const normalizedBase = base.endsWith('/') ? base : `${base}/`;
+  const cleanSub = subpath.startsWith('/') ? subpath.slice(1) : subpath;
+  return `${normalizedBase}${cleanSub}`;
+}
+
+export function saveActiveUserLocally(user: ClientUserProfile | null) {
+  if (typeof window === 'undefined') return;
+  if (!user) {
+    localStorage.removeItem(STORAGE_USER_KEY);
+  } else {
+    localStorage.setItem(STORAGE_USER_KEY, JSON.stringify(user));
+  }
+  window.dispatchEvent(new CustomEvent('dtt-auth-changed', { detail: user }));
+}
+
+export function getLocalActiveUser(): ClientUserProfile | null {
+  if (typeof window === 'undefined') return null;
+  try {
+    const raw = localStorage.getItem(STORAGE_USER_KEY);
+    return raw ? (JSON.parse(raw) as ClientUserProfile) : null;
+  } catch {
+    return null;
+  }
+}
+
+export function recordReauthTimestamp() {
+  if (typeof window === 'undefined') return;
+  localStorage.setItem(STORAGE_REAUTH_KEY, String(Date.now()));
+}
+
+export function getLastReauthTimestamp(): number | null {
+  if (typeof window === 'undefined') return null;
+  const raw = localStorage.getItem(STORAGE_REAUTH_KEY);
+  if (!raw) return null;
+  const parsed = Number(raw);
+  return Number.isFinite(parsed) ? parsed : null;
+}
+
+export async function checkWebAuthnCapabilities(): Promise<{
+  supported: boolean;
+  platformAuthenticatorAvailable: boolean;
+  conditionalMediationAvailable: boolean;
+}> {
+  if (typeof window === 'undefined' || !window.PublicKeyCredential) {
+    return {
