+// Client-side helper that catches blocked outbound requests gracefully without unhandled rejections.
+export async function fetchWithPolicyHandling(url, { statusElement, ...fetchOptions } = {}) {
+  try {
+    const response = await fetch(url, fetchOptions);
+    const contentType = response.headers.get('content-type') || '';
+    const data = contentType.includes('application/json')
+      ? await response.json()
+      : await response.text();
+
+    if (!response.ok) {
+      const serverMessage =
+        typeof data === 'object' && data !== null && data.error
+          ? data.error
+          : `HTTP ${response.status}`;
+      throw new Error(serverMessage);
+    }
+
+    if (statusElement) {
+      const successMessage =
+        typeof data === 'object' && data !== null && data.message
+          ? data.message
+          : 'Thank you for subscribing to The Daily Grind newsletter!';
+      statusElement.textContent = successMessage;
+      statusElement.dataset.status = 'success';
+      statusElement.className = 'status-msg status-success';
+    }
+    return { ok: true, body: data, error: null };
+  } catch (error) {
+    const message = error instanceof Error ? error.message : String(error);
+    if (statusElement) {
+      statusElement.textContent = `We couldn't complete your request (${message}). For your security, connections outside The Daily Grind are blocked.`;
+      statusElement.dataset.status = 'error';
+      statusElement.className = 'status-msg status-error';
+    }
+    return { ok: false, body: null, error };
+  }
+}
+
+// Fallback for browsers without native CSS :user-invalid support
+const UserInvalidFallback = (() => {
+  const dirtyState = new WeakMap();
+
+  const updateState = (input) => {
+    const isValid = input.checkValidity();
+    input.classList.toggle('user-invalid-fallback', !isValid);
+    input.classList.toggle('user-valid-fallback', isValid);
+
+    if (!isValid) {
+      input.setAttribute('aria-invalid', 'true');
+    } else {
+      input.removeAttribute('aria-invalid');
+    }
+  };
+
+  const handleEvent = (event) => {
+    const input = event.target;
+
+    if (event.type === 'reset') {
+      const controls = input.elements || [];
+      for (const control of controls) {
+        dirtyState.delete(control);
+        control.classList.remove('user-invalid-fallback', 'user-valid-fallback');
+        control.removeAttribute('aria-invalid');
+      }
+      return;
+    }
+
+    if (!input || typeof input.checkValidity !== 'function') return;
+
+    if (event.type === 'input' || event.type === 'change') {
+      const state = dirtyState.get(input) || { hasInteracted: false, hasBlurred: false };
+      state.hasInteracted = true;
+      dirtyState.set(input, state);
+      if (state.hasBlurred) {
+        updateState(input);
+      }
+    } else if (event.type === 'blur') {
+      const state = dirtyState.get(input) || { hasInteracted: false, hasBlurred: false };
+      state.hasBlurred = true;
+      dirtyState.set(input, state);
+      if (state.hasInteracted) {
+        updateState(input);
+      }
+    }
+  };
+
+  const init = (root = document) => {
+    if (typeof CSS !== 'undefined' && CSS.supports('selector(:user-invalid)')) return;
+
+    root.addEventListener('blur', handleEvent, true);
+    root.addEventListener('input', handleEvent);
+    root.addEventListener('change', handleEvent);
+    root.addEventListener('reset', handleEvent, true);
+  };
+
+  return { init };
+})();
