+if (typeof window !== 'undefined') {
+  window.fetchWithPolicyHandling = fetchWithPolicyHandling;
+  if (document.readyState === 'loading') {
+    document.addEventListener('DOMContentLoaded', initNewsletterForm);
+  } else {
+    initNewsletterForm();
+  }
+}
