+        if (!hash || hash === '#') return;
+
+        const targetElement = document.querySelector(hash);
+        if (!targetElement) return;
+
+        event.preventDefault();
+        history.pushState(null, '', hash);
+        await scrollToAndHighlight(targetElement, link);
+      });
+    });
