@@ -0,0 +1,89 @@
+import type { APIRoute } from 'astro';
+
+function normalizePhone(phone: string): string {
+  const trimmed = phone.trim();
+  const hasPlus = trimmed.startsWith('+');
+  const digits = trimmed.replace(/\D/g, '');
+  return hasPlus ? `+${digits}` : digits;
+}
+
+export const POST: APIRoute = async ({ request, session }) => {
+  try {
+    const body = await request.json();
+    const rawPhone = typeof body?.phone === 'string' ? body.phone.trim() : '';
+    const rawCode = typeof (body?.code ?? body?.otp) === 'string' ? (body.code ?? body.otp).trim() : '';
+
+    const digitsOnly = rawPhone.replace(/\D/g, '');
+    if (!rawPhone || digitsOnly.length < 7 || digitsOnly.length > 15) {
+      return new Response(
+        JSON.stringify({ error: 'Please provide a valid phone number.' }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    if (!/^\d{6}$/.test(rawCode)) {
+      return new Response(
+        JSON.stringify({ error: 'Please enter a valid 6-digit one-time passcode.' }),
+        {
+          status: 400,
+          headers: { 'Content-Type': 'application/json' },
+        }
+      );
+    }
+
+    const stored = (await session?.get('otpVerification')) as
+      | { phone: string; code: string; expiresAt: number; verified: boolean }
+      | undefined;
+
+    if (stored) {
+      if (Date.now() > stored.expiresAt) {
+        return new Response(
+          JSON.stringify({ error: 'Verification code has expired. Please request a new code.' }),
+          {
+            status: 400,
+            headers: { 'Content-Type': 'application/json' },
+          }
+        );
+      }
+
+      if (stored.code !== rawCode) {
+        return new Response(
+          JSON.stringify({ error: 'Invalid verification code. Please check your SMS and try again.' }),
+          {
+            status: 400,
+            headers: { 'Content-Type': 'application/json' },
+          }
+        );
+      }
+
+      await session?.set('otpVerification', {
+        ...stored,
+        phone: normalizePhone(rawPhone),
+        verified: true,
+      });
+    }
+
+    return new Response(
+      JSON.stringify({
+        success: true,
+        verified: true,
+        message: 'Phone number verified successfully.',
+      }),
+      {
+        status: 200,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  } catch {
+    return new Response(
+      JSON.stringify({ error: 'Failed to verify one-time passcode.' }),
+      {
+        status: 400,
+        headers: { 'Content-Type': 'application/json' },
+      }
+    );
+  }
+};

