+          const formData = new FormData(signupForm);
+          const response = await fetch(signupForm.action, {
+            method: 'POST',
+            headers: {
+              Accept: 'application/json',
+              'Content-Type': 'application/x-www-form-urlencoded',
+            },
+            body: new URLSearchParams(formData),
+          });
+
+          const result = await response.json();
+
+          if (statusBox) {
+            statusBox.hidden = false;
+            if (result.emailVerified) {
+              statusBox.classList.add('status-verified');
+              statusBox.textContent = result.message;
+            } else if (response.ok) {
+              statusBox.classList.add('status-pending');
+              statusBox.textContent = result.message;
+            } else {
+              statusBox.classList.add('status-error');
+              statusBox.textContent = result.message || 'Unable to complete registration.';
+            }
+          }
+
+          if (response.ok) {
+            signupForm.reset();
+            if (tokenInput) {
+              tokenInput.value = '';
+            }
+            await refreshFormNonce();
+          }
+        } catch {
+          // If AJAX submission fails, fall back to standard form submission
+          signupForm.submit();
+          return;
+        } finally {
+          if (submitBtn) {
+            submitBtn.disabled = false;
+            submitBtn.textContent = 'Create Rewards Account';
+          }
+        }
+      });
+    }
+  </script>
 </body>

