+/**
+ * The Daily Grind - Accessible, Reusable Web Components
+ * Provides encapsulated Shadow DOM styling, ARIA accessibility, keyboard navigation,
+ * and event-driven inter-component communication.
+ */
+
+const SHARED_THEME_VARS = `
+  :host {
+    --primary: var(--dg-primary, #4e342e);
+    --primary-dark: var(--dg-primary-dark, #3e2723);
+    --secondary: var(--dg-secondary, #d7ccc8);
+    --accent: var(--dg-accent, #ffab40);
+    --accent-hover: var(--dg-accent-hover, #ff9100);
+    --text: var(--dg-text, #3e2723);
+    --text-muted: var(--dg-text-muted, #6d4c41);
+    --light: var(--dg-light, #fafafa);
+    --surface: var(--dg-surface, #ffffff);
+    --radius: 10px;
+    --shadow-sm: 0 2px 8px rgba(62, 39, 35, 0.08);
+    --shadow-md: 0 8px 24px rgba(62, 39, 35, 0.14);
+    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
+    color: var(--text);
+    box-sizing: border-box;
+  }
+  *, *::before, *::after {
+    box-sizing: border-box;
+  }
+  :focus-visible {
+    outline: 3px solid var(--accent);
+    outline-offset: 2px;
+  }
+`;
+
+/**
+ * 1. <daily-grind-navbar> / <dg-navbar>
+ * Encapsulated navigation header with responsive menu toggle and live cart counter badge.
+ */
+export class DailyGrindNavbar extends HTMLElement {
+  static get observedAttributes() {
+    return ['brand', 'cart-count'];
+  }
+
+  constructor() {
+    super();
+    this.attachShadow({ mode: 'open' });
+    this._cartCount = 0;
+    this._mobileMenuOpen = false;
+    this._onExternalCartUpdate = this._onExternalCartUpdate.bind(this);
+  }
+
+  connectedCallback() {
+    if (this.hasAttribute('cart-count')) {
+      this._cartCount = parseInt(this.getAttribute('cart-count'), 10) || 0;
+    }
+    this.render();
+    window.addEventListener('dg-cart-state', this._onExternalCartUpdate);
+  }
+
+  disconnectedCallback() {
+    window.removeEventListener('dg-cart-state', this._onExternalCartUpdate);
+  }
+
+  attributeChangedCallback(name, oldVal, newVal) {
+    if (oldVal === newVal) return;
+    if (name === 'cart-count') {
+      this._cartCount = parseInt(newVal, 10) || 0;
+      this._updateBadge();
+    } else {
+      this.render();
+    }
+  }
+
+  _onExternalCartUpdate(e) {
+    if (e.detail && typeof e.detail.totalItems === 'number') {
+      this._cartCount = e.detail.totalItems;
+      this._updateBadge();
+    }
+  }
+
+  _updateBadge() {
+    const badge = this.shadowRoot.querySelector('.cart-badge');
+    const cartBtn = this.shadowRoot.querySelector('.cart-trigger');
+    if (badge && cartBtn) {
+      badge.textContent = String(this._cartCount);
+      cartBtn.setAttribute('aria-label', `Open coffee order bag, ${this._cartCount} items`);
+      badge.classList.remove('pulse');
+      void badge.offsetWidth;
+      badge.classList.add('pulse');
+    }
+  }
